rows.before:
#success-placeholder td {
  	border: 1px #ccc solid;
  	margin: 0;
  	padding: 1px;
   text-align:center;
  }
  #success-placeholder .bad {
  	background-color: #fcc;
  }
  #success-placeholder .good {
  	background-color: #cfc;
  }
  #success-placeholder th:first-child {
  	width: 30%;
  }
  #success-placeholder th {
  	width: 10%;
  }
  #success-placeholder table {
  	width: 100%;
  }

rows.after:
#success-placeholder td {
  	border: 1px var(--app-border) solid;
  	margin: 0;
  	padding: 0.0625rem;
   text-align:center;
  }
  #success-placeholder .bad {
  	background-color: var(--app-danger-bg);
  }
  #success-placeholder .good {
  	background-color: var(--app-success-bg);
  }
  #success-placeholder th:first-child {
  	width: 30%;
  }
  #success-placeholder th {
  	width: 10%;
  }
  #success-placeholder table {
  	width: 100%;
  }
